{
  "nl": {
    "issue": [
      {
        "text": "合伙人如何履行出资义务；一个或数个合伙人不履行出资义务时，其他合伙人能否拒绝出资",
        "rules": ["c968-1", "c968-2"]
      },
      {
        "text": "合伙财产的范围，以及合伙合同终止前合伙人能否请求分割合伙财产",
        "rules": ["c969-1a", "c969-1b", "c969-1c", "c969-2"]
      },
      {
        "text": "合伙事务如何作出决定、如何执行；委托执行、其他合伙人的监督权与异议的效力",
        "rules": ["c970-1", "c970-1-exc", "c970-2a", "c970-2b", "c970-2c", "c970-2d", "c970-3a", "c970-3b"]
      },
      {
        "text": "合伙人因执行合伙事务能否请求支付报酬",
        "rules": ["c971", "c971-exc"]
      },
      {
        "text": "合伙的利润分配与亏损分担的适用顺序",
        "rules": ["c972-1", "c972-2", "c972-3", "c972-4"]
      },
      {
        "text": "合伙人对合伙债务的责任，以及超额清偿后的追偿权",
        "rules": ["c973-1", "c973-2"]
      },
      {
        "text": "合伙人向合伙人以外的人转让财产份额的限制",
        "rules": ["c974", "c974-exc"]
      },
      {
        "text": "合伙人的债权人能否代位行使合伙人的权利",
        "rules": ["c975", "c975-exc"]
      },
      {
        "text": "不定期合伙的认定、合伙期限届满后的续行与随时解除",
        "rules": ["c976-1", "c976-2", "c976-3a", "c976-3b"]
      }
    ],
    "conditions": [
      {
        "text": "存在合伙合同，行为人是该合伙合同的合伙人",
        "rules": ["c968-1", "c969-1a", "c970-1", "c973-1", "c976-3a"]
      },
      {
        "text": "合伙合同约定了出资方式、数额和缴付期限",
        "rules": ["c968-1"]
      },
      {
        "text": "财产为合伙人的出资，或因合伙事务依法取得的收益，或其他依法属于合伙的财产",
        "rules": ["c969-1a", "c969-1b", "c969-1c"]
      },
      {
        "text": "就合伙事务作出决定；依合伙合同约定或全体合伙人决定委托执行；合伙人分别执行合伙事务",
        "rules": ["c970-1", "c970-2b", "c970-3a"]
      },
      {
        "text": "对利润分配、亏损分担没有约定或约定不明确，协商不成，且无法确定实缴出资比例",
        "rules": ["c972-2", "c972-3", "c972-4"]
      },
      {
        "text": "对合伙期限没有约定或约定不明确且依第510条仍不能确定；或合伙期限届满后合伙人继续执行合伙事务而其他合伙人未提出异议",
        "rules": ["c976-1", "c976-2"]
      }
    ],
    "exceptions": [
      {
        "text": "合伙合同另有约定时，事务决定的一致同意、不得请求报酬、对外转让份额须经一致同意均不适用",
        "rules": ["c970-1-exc", "c971-exc", "c974-exc"]
      },
      {
        "text": "合伙合同终止前不得请求分割合伙财产；终止后不受该限制（第969条第2款的反面解释）",
        "rules": ["c969-2"]
      },
      {
        "text": "合伙合同对利润分配和亏损分担有约定时，按约定办理，不适用协商、实缴出资比例、平均分担",
        "rules": ["c972-1"]
      },
      {
        "text": "合伙人享有的利益分配请求权不受代位权限制，合伙人的债权人可以代位行使",
        "rules": ["c975-exc"]
      }
    ],
    "effects": [
      {
        "text": "合伙人应当按照约定的出资方式、数额和缴付期限履行出资义务；其他合伙人不得因一个或数个合伙人不履行出资义务而拒绝出资",
        "rules": ["c968-1", "c968-2"]
      },
      {
        "text": "出资、因合伙事务依法取得的收益和其他财产属于合伙财产；合伙合同终止前合伙人不得请求分割",
        "rules": ["c969-1a", "c969-1b", "c969-1c", "c969-2"]
      },
      {
        "text": "合伙事务的决定除合伙合同另有约定外须经全体合伙人一致同意；合伙事务由全体合伙人共同执行，可依约定或全体合伙人决定委托一个或数个合伙人执行，其他合伙人不再执行但有权监督；执行事务合伙人对其他合伙人执行的事务提出异议后，其他合伙人应当暂停该项事务的执行",
        "rules": ["c970-1", "c970-2a", "c970-2b", "c970-2c", "c970-2d", "c970-3a", "c970-3b"]
      },
      {
        "text": "合伙人不得因执行合伙事务请求支付报酬；合伙合同另有约定的，可以请求",
        "rules": ["c971", "c971-exc"]
      },
      {
        "text": "利润分配和亏损分担依次按合伙合同约定、合伙人协商决定、实缴出资比例、平均分配分担办理",
        "rules": ["c972-1", "c972-2", "c972-3", "c972-4"]
      },
      {
        "text": "合伙人对合伙债务承担连带责任；清偿合伙债务超过自己应当承担份额的合伙人有权向其他合伙人追偿",
        "rules": ["c973-1", "c973-2"]
      },
      {
        "text": "合伙人向合伙人以外的人转让全部或者部分财产份额，须经其他合伙人一致同意；合伙合同另有约定的从其约定",
        "rules": ["c974", "c974-exc"]
      },
      {
        "text": "合伙人的债权人不得代位行使合伙人依照本章规定和合伙合同享有的权利，但利益分配请求权除外",
        "rules": ["c975", "c975-exc"]
      },
      {
        "text": "视为不定期合伙；期限届满后继续执行且无异议的原合伙合同继续有效但期限为不定期；合伙人可以随时解除不定期合伙合同，但应当在合理期限之前通知其他合伙人",
        "rules": ["c976-1", "c976-2", "c976-3a", "c976-3b"]
      }
    ],
    "priority": [
      {
        "text": "依合伙合同约定或全体合伙人决定委托部分合伙人执行合伙事务时，其他合伙人不再执行合伙事务，优先于全体合伙人共同执行",
        "rules": ["c970-2c", "c970-2a"]
      },
      {
        "text": "利润分配与亏损分担：合伙合同约定优先于协商决定，协商决定优先于按实缴出资比例，能确定出资比例时不适用平均分担",
        "rules": ["c972-1", "c972-2", "c972-3", "c972-4"]
      },
      {
        "text": "合伙合同另有约定优先于第970条第1款、第971条、第974条的任意性规定",
        "rules": ["c970-1-exc", "c971-exc", "c974-exc"]
      },
      {
        "text": "利益分配请求权的代位行使优先于第975条前段的一般禁止",
        "rules": ["c975-exc", "c975"]
      }
    ],
    "distinguish": [
      {
        "text": "LEGO 卡片称未经其他合伙人一致同意对外转让财产份额“无效”，法条仅规定“须经其他合伙人一致同意”，未明定无效后果",
        "rules": []
      },
      {
        "text": "LEGO 卡片称合伙人死亡、丧失行为能力或终止时合伙合同原则上终止，本章未作规定，不能作为法条规则",
        "rules": []
      },
      {
        "text": "LEGO 卡片称本节为民事合伙，不适用《公司法》《合伙企业法》等商事主体制度，属学理说明，法条未规定",
        "rules": []
      },
      {
        "text": "合伙合同与委托合同不同：合伙以共同事业、共享利益、共担风险为要件，委托合同不以之为要件（学理）",
        "rules": []
      },
      {
        "text": "笔记“其他合伙人不能因他人不出资而拒绝出资”系学理补充，第968条未明文规定",
        "rules": ["c968-2"]
      }
    ]
  },
